<script setup>
import { onMounted, onUnmounted, ref } from "vue";
import UiIcon from "../../components/UiIcon.vue";
import { getAdminSystemStatus } from "../../services/adminRepository";
const data=ref(null),loading=ref(true),error=ref(""),auto=ref(false);let timer;const labels={ok:"正常",ready:"已就绪",empty:"空知识库",unknown:"未知"};async function load(){loading.value=true;error.value="";try{data.value=await getAdminSystemStatus()}catch(e){error.value=e.response?.data?.message||e.message||"系统状态加载失败"}finally{loading.value=false}}function toggle(){clearInterval(timer);if(auto.value)timer=setInterval(load,60000)}onMounted(load);onUnmounted(()=>clearInterval(timer));
</script>
<template><main class="portal-page admin-portal page-enter"><div class="portal-heading"><div><span class="portal-kicker">系统状态</span><h1>平台运行状态</h1><p>状态来自管理员探针；未知状态不会被猜测为正常。</p></div><div><label class="admin-auto-refresh"><input v-model="auto" type="checkbox" @change="toggle" /> 每 60 秒自动刷新</label><button class="secondary-button" @click="load" :disabled="loading"><UiIcon name="PhArrowClockwise" />手动刷新</button></div></div><div v-if="loading" class="portal-loading"><i v-for="n in 4" :key="n"></i></div><div v-else-if="error" class="portal-error"><strong>{{ error }}</strong><button class="secondary-button" @click="load">重试</button></div><template v-else-if="data"><section class="system-status-board"><article><span><UiIcon name="PhPulse" :size="24" /></span><div><h2>API 服务</h2><p>{{ data.api_version }} · {{ data.app_environment }}</p></div><em>{{ labels[data.api_status]||data.api_status }}</em></article><article><span><UiIcon name="PhFolderOpen" :size="24" /></span><div><h2>数据库</h2><p>查询延迟 {{ data.database_query_latency_ms }} ms</p></div><em>{{ labels[data.database_status]||data.database_status }}</em></article><article><span><UiIcon name="PhBookOpen" :size="24" /></span><div><h2>知识库</h2><p>{{ data.document_count }} 份文档 · {{ data.chunk_count }} 个知识块</p></div><em>{{ labels[data.knowledge_base_status]||data.knowledge_base_status }}</em></article><article><span><UiIcon name="PhRobot" :size="24" /></span><div><h2>LLM</h2><p>提供商：{{ data.llm_provider }}</p></div><em>{{ data.llm_available?"可用":"不可用" }}</em></article></section><section class="portal-panel admin-status-detail"><h2>状态说明</h2><dl><div><dt>上传目录</dt><dd>{{ data.upload_storage_writable?"可写":"不可写或不存在" }}</dd></div><div><dt>任务调度</dt><dd>{{ data.scheduler_status }}</dd></div><div><dt>降级模式</dt><dd>{{ data.fallback_mode_enabled?"已启用":"未启用" }}</dd></div><div><dt>服务器时间</dt><dd>{{ new Date(data.server_time).toLocaleString("zh-CN") }}</dd></div><div><dt>最近错误</dt><dd>{{ data.recent_error_summary||"暂无可报告错误" }}</dd></div></dl></section></template></main></template>
